335. #[cfg(test)]
336. mod tests {
337.     extern crate std;
338. 
339.     use super::{
340.         BssStorage,
341.         BumpAllocError,
342.         FixedSizeBumpAllocator,
343.     };
344.     use std::vec::Vec;
345. 
346.     #[repr(align(8))]
347.     struct StorageA {
348.         bytes: [u8; 16],
349.     }
350. 
351.     static mut STORAGE_A: StorageA = StorageA { bytes: [0; 16] };
352. 
353.     struct BackendA;
354. 
355.     unsafe impl BssStorage for BackendA {
356.         const NUM_UNITS: usize = 2;
357.         const STORAGE_SIZE: usize = 16;
358. 
359.         fn as_mut_ptr() -> *mut u8 {
360.             unsafe { core::ptr::addr_of_mut!(STORAGE_A.bytes) as *mut u8 }
361.         }
362.     }
363. 
364.     static ALLOC_A: FixedSizeBumpAllocator<8, 8, BackendA> =
365.         unsafe { FixedSizeBumpAllocator::new() };
366. 
367.     #[test]
368.     fn alloc_returns_distinct_slots() {
369.         let first: *mut u8 = ALLOC_A.alloc().expect("first alloc failed").as_mut_ptr();
370.         let second: *mut u8 = ALLOC_A.alloc().expect("second alloc failed").as_mut_ptr();
371.         assert_ne!(first, second);
372.     }
373. 
374.     #[repr(align(4))]
375.     struct StorageB {
376.         bytes: [u8; 8],
377.     }
378. 
379.     static mut STORAGE_B: StorageB = StorageB { bytes: [0; 8] };
380. 
381.     struct BackendB;
382. 
383.     unsafe impl BssStorage for BackendB {
384.         const NUM_UNITS: usize = 1;
385.         const STORAGE_SIZE: usize = 8;
386. 
387.         fn as_mut_ptr() -> *mut u8 {
388.             unsafe { core::ptr::addr_of_mut!(STORAGE_B.bytes) as *mut u8 }
389.         }
390.     }
391. 
392.     static ALLOC_B: FixedSizeBumpAllocator<8, 4, BackendB> =
393.         unsafe { FixedSizeBumpAllocator::new() };
394. 
395.     #[test]
396.     fn alloc_as_allows_typed_access() {
397.         let slot: &mut core::mem::MaybeUninit<[u32; 2]> =
398.             unsafe { ALLOC_B.alloc_as::<[u32; 2]>().expect("alloc_as failed") };
399.         slot.write([7, 11]);
400.         let typed: &mut [u32; 2] = unsafe { slot.assume_init_mut() };
401.         let values: Vec<u32> = Vec::from(*typed);
402.         assert_eq!(values, vec![7, 11]);
403.     }
404. 
405.     #[repr(align(8))]
406.     struct StorageC {
407.         bytes: [u8; 8],
408.     }
409. 
410.     static mut STORAGE_C: StorageC = StorageC { bytes: [0; 8] };
411. 
412.     struct BackendC;
413. 
414.     unsafe impl BssStorage for BackendC {
415.         const NUM_UNITS: usize = 1;
416.         const STORAGE_SIZE: usize = 8;
417. 
418.         fn as_mut_ptr() -> *mut u8 {
419.             unsafe { core::ptr::addr_of_mut!(STORAGE_C.bytes) as *mut u8 }
420.         }
421.     }
422. 
423.     static ALLOC_C: FixedSizeBumpAllocator<8, 8, BackendC> =
424.         unsafe { FixedSizeBumpAllocator::new() };
425. 
426.     #[test]
427.     fn alloc_returns_exhausted_error() {
428.         let _ = ALLOC_C.alloc().expect("first alloc failed");
429.         let result = ALLOC_C.alloc();
430.         assert_eq!(result.unwrap_err(), BumpAllocError::Exhausted);
431.     }
432. }
